// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalStateException;

import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

class LmdbNativeIdDomainTest {

	@Test
	void unionReadsEachMemberHeadOnceInsteadOfRescanningEveryDomain() {
		int members = 100;
		int rows = 128;
		AtomicInteger headReads = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		LmdbNativeIdDomain[] domains = new LmdbNativeIdDomain[members];
		for (int p = 0; p < members; p++) {
			long[] ids = new long[rows];
			for (int i = 0; i < rows; i++) {
				ids[i] = (long) i * members + p;
			}
			domains[p] = new ObservedDomain(ids, 1L, headReads, closes);
		}
		try (LmdbNativeIdDomain union = LmdbNativeIdDomain.union(domains)) {
			assertThat(union.cardinalityUpperBound()).isEqualTo((long) rows * members);
			for (long expected = 0; expected < (long) rows * members; expected++) {
				assertThat(union.advance()).isTrue();
				assertThat(union.current()).isEqualTo(expected);
				assertThat(union.multiplicity()).isEqualTo(1L);
			}
			assertThat(union.advance()).isFalse();
			assertThat(headReads.get()).as("one cached head read per input value")
					.isLessThanOrEqualTo(rows * members);
		}
		assertThat(closes.get()).isEqualTo(members);
	}

	@Test
	void nestedUnionPreservesUnsignedOrderMultiplicitySeeksAndClosure() {
		AtomicInteger reads = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		LmdbNativeIdDomain nested = LmdbNativeIdDomain.union(new LmdbNativeIdDomain[] {
				new ObservedDomain(new long[] { 0L, 7L, Long.MIN_VALUE }, 2L, reads, closes),
				new ObservedDomain(new long[] { 7L, -1L }, 3L, reads, closes) });
		LmdbNativeIdDomain union = LmdbNativeIdDomain.union(new LmdbNativeIdDomain[] {
				nested, new ObservedDomain(new long[0], 1L, reads, closes),
				new ObservedDomain(new long[] { 7L, Long.MIN_VALUE, -1L }, 5L, reads, closes) });
		try (union) {
			assertThat(union.advance()).isTrue();
			assertThat(union.current()).isZero();
			assertThat(union.multiplicity()).isEqualTo(2L);
			assertThat(union.seekAtLeast(1L)).isTrue();
			assertThat(union.current()).isEqualTo(7L);
			assertThat(union.multiplicity()).isEqualTo(10L);
			assertThat(union.advance()).isTrue();
			assertThat(union.current()).isEqualTo(Long.MIN_VALUE);
			assertThat(union.multiplicity()).isEqualTo(7L);
			assertThat(union.seekAtLeast(-2L)).isTrue();
			assertThat(union.current()).isEqualTo(-1L);
			assertThat(union.multiplicity()).isEqualTo(8L);
			assertThat(union.advance()).isFalse();
			assertThatIllegalStateException().isThrownBy(union::current);
			assertThat(union.seekAtLeast(7L)).isTrue();
			assertThat(union.current()).isEqualTo(7L);
			assertThat(union.multiplicity()).isEqualTo(10L);
			assertThat(union.seekAtLeast(0L)).isTrue();
			assertThat(union.current()).isZero();
		}
		union.close();
		assertThat(closes.get()).isEqualTo(4);
		assertThat(union.advance()).isFalse();
		assertThat(union.seekAtLeast(0L)).isFalse();
	}

	@Test
	void overlappingMultiplicitySaturatesWithoutOverflow() {
		AtomicInteger reads = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		try (LmdbNativeIdDomain union = LmdbNativeIdDomain.union(new LmdbNativeIdDomain[] {
				new ObservedDomain(new long[] { 1L }, Long.MAX_VALUE, reads, closes),
				new ObservedDomain(new long[] { 1L }, 2L, reads, closes) })) {
			assertThat(union.seekAtLeast(1L)).isTrue();
			assertThat(union.multiplicity()).isEqualTo(Long.MAX_VALUE);
			assertThat(union.advance()).isFalse();
		}
	}

	private static final class ObservedDomain implements LmdbNativeIdDomain {
		private final LmdbNativeIdDomain delegate;
		private final long multiplicity;
		private final AtomicInteger reads;
		private final AtomicInteger closes;

		ObservedDomain(long[] ids, long multiplicity, AtomicInteger reads, AtomicInteger closes) {
			this.delegate = LmdbNativeIdDomain.sortedDistinct(ids);
			this.multiplicity = multiplicity;
			this.reads = reads;
			this.closes = closes;
		}

		@Override
		public long cardinalityUpperBound() {
			return delegate.cardinalityUpperBound();
		}

		@Override
		public boolean advance() {
			return delegate.advance();
		}

		@Override
		public boolean seekAtLeast(long id) {
			return delegate.seekAtLeast(id);
		}

		@Override
		public long current() {
			reads.incrementAndGet();
			return delegate.current();
		}

		@Override
		public long multiplicity() {
			return multiplicity;
		}

		@Override
		public void close() {
			closes.incrementAndGet();
			delegate.close();
		}
	}
}
